//! Files `just generate` writes from code, and `just openapi-check` compares
//! against the checked-in copies. The daemon's `generate_openapi` binary and
//! `piquelctl`'s `cli_reference` example both write through [`Artifacts`],
//! and render the documentation's reference pages with [`Page`].

use std::{
    fmt::Write as _,
    fs, io,
    path::{Path, PathBuf},
};

/// Writes generated files into the repository, or in check mode compares
/// them with the checked-in ones.
pub struct Artifacts {
    /// Repository root that artifact paths are relative to.
    root: PathBuf,
    /// Whether to compare instead of writing.
    check: bool,
}

/// Why generated files could not be written or checked.
#[derive(Debug, thiserror::Error)]
pub enum ArtifactError {
    /// The command line was neither empty nor `--check`.
    #[error("unexpected arguments {0:?}; pass nothing to write, or --check to compare")]
    Usage(Vec<String>),
    /// The repository root could not be found from this crate's location.
    #[error("locate the repository root")]
    Root(#[source] io::Error),
    /// A checked-in file could not be read.
    #[error("read {}", .path.display())]
    Read {
        /// The file.
        path: PathBuf,
        /// What went wrong.
        #[source]
        source: io::Error,
    },
    /// A generated file could not be written.
    #[error("write {}", .path.display())]
    Write {
        /// The file.
        path: PathBuf,
        /// What went wrong.
        #[source]
        source: io::Error,
    },
    /// Checked-in files differ from the generated ones, or are missing.
    #[error("generated artifacts are out of date: {}; run just generate", .0.join(", "))]
    Stale(Vec<String>),
}

impl Artifacts {
    /// Reads the mode from the command line: no arguments writes, `--check`
    /// compares.
    ///
    /// # Errors
    /// On other arguments, or if the repository root cannot be found.
    pub fn from_args() -> Result<Self, ArtifactError> {
        let args = std::env::args().skip(1).collect::<Vec<_>>();
        let check = match args.as_slice() {
            [] => false,
            [flag] if flag == "--check" => true,
            _ => return Err(ArtifactError::Usage(args)),
        };
        // This crate lives two levels below the root, in `crates/piqueld-generated`.
        let root = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../..")
            .canonicalize()
            .map_err(ArtifactError::Root)?;
        Ok(Self { root, check })
    }

    /// The repository root.
    #[must_use]
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// Writes each `(path, contents)` artifact, `path` relative to the root,
    /// or in check mode compares them all with the checked-in files.
    ///
    /// # Errors
    /// If a file cannot be read or written, or in check mode if any is stale
    /// or missing.
    pub fn sync<'a>(
        &self,
        artifacts: impl IntoIterator<Item = (&'a str, String)>,
    ) -> Result<(), ArtifactError> {
        let mut stale = Vec::new();
        for (relative, contents) in artifacts {
            let path = self.root.join(relative);
            if self.check {
                match fs::read_to_string(&path) {
                    Ok(existing) if existing == contents => println!("{relative} is up to date"),
                    Ok(_) => stale.push(relative.to_owned()),
                    Err(error) if error.kind() == io::ErrorKind::NotFound => {
                        stale.push(relative.to_owned());
                    }
                    Err(source) => return Err(ArtifactError::Read { path, source }),
                }
            } else {
                fs::write(&path, contents)
                    .map_err(|source| ArtifactError::Write { path, source })?;
                println!("wrote {relative}");
            }
        }
        if stale.is_empty() {
            Ok(())
        } else {
            Err(ArtifactError::Stale(stale))
        }
    }
}

/// A generated Markdown page for the documentation book, written top to
/// bottom.
pub struct Page {
    text: String,
    /// Whether the page ends with a list item, which the next one continues.
    in_list: bool,
}

impl Page {
    /// Starts a page: a comment telling readers not to edit it and naming
    /// `source`, then its title and the hand-written `intro`.
    #[must_use]
    pub fn new(source: &str, title: &str, intro: &str) -> Self {
        Self {
            text: format!(
                "<!-- Generated by `just generate` from {source}. Do not edit it by hand. -->\n\n# {title}\n\n{intro}\n"
            ),
            in_list: false,
        }
    }

    /// Adds a heading of `level` (2 for `##`).
    pub fn heading(&mut self, level: usize, text: &str) {
        let _ = write!(self.text, "\n{} {text}\n", "#".repeat(level));
        self.in_list = false;
    }

    /// Adds doc-comment or help `text` as paragraphs, see [`Self::prose`].
    pub fn paragraphs(&mut self, text: &str) {
        let _ = write!(self.text, "\n{}\n", Self::prose(text));
        self.in_list = false;
    }

    /// Adds `text` verbatim in a `text` code block.
    pub fn code(&mut self, text: &str) {
        let _ = write!(self.text, "\n```text\n{}\n```\n", text.trim_end());
        self.in_list = false;
    }

    /// Adds a list item nested `depth` levels deep, whose Markdown `text`
    /// may have several paragraphs. Items added one after another form one
    /// list.
    pub fn item(&mut self, depth: usize, text: &str) {
        if !self.in_list {
            self.text.push('\n');
        }
        let indent = "  ".repeat(depth);
        let _ = write!(self.text, "{indent}- ");
        for (index, line) in text.lines().enumerate() {
            if index > 0 && !line.is_empty() {
                let _ = write!(self.text, "{indent}  ");
            }
            let _ = writeln!(self.text, "{line}");
        }
        self.in_list = true;
    }

    /// The finished page.
    #[must_use]
    pub fn finish(self) -> String {
        self.text
    }

    /// Turns doc-comment or help text into Markdown: lines of a paragraph
    /// are joined, except list items, and a `<` outside code spans is
    /// escaped so it doesn't open an HTML tag. Fenced code blocks stay as
    /// they are.
    ///
    /// ```text
    /// "Becomes `<host>.ts.net`, see\n<host>." -> "Becomes `<host>.ts.net`, see \<host>."
    /// ```
    #[must_use]
    pub fn prose(text: &str) -> String {
        let mut blocks = Vec::new();
        let mut prose = Vec::new();
        let mut lines = text.trim().lines();
        while let Some(line) = lines.next() {
            let Some(fence) = Fence::open(line) else {
                prose.push(line);
                continue;
            };
            blocks.push(Self::paragraph(&prose));
            prose.clear();
            let mut code = vec![line];
            for line in lines.by_ref() {
                code.push(line);
                if fence.closes(line) {
                    break;
                }
            }
            blocks.push(code.join("\n"));
        }
        blocks.push(Self::paragraph(&prose));
        blocks.retain(|block| !block.is_empty());
        blocks.join("\n\n")
    }

    /// [`Self::prose`] for `lines` without code blocks.
    fn paragraph(lines: &[&str]) -> String {
        let mut joined = String::new();
        for line in lines.iter().map(|line| line.trim()) {
            if !joined.is_empty() && !joined.ends_with('\n') {
                joined.push(if line.is_empty() || line.starts_with("- ") {
                    '\n'
                } else {
                    ' '
                });
            }
            if line.is_empty() {
                joined.push('\n');
            }
            joined.push_str(line);
        }
        joined
            .trim()
            .split('`')
            .enumerate()
            .map(|(index, part)| {
                if index % 2 == 0 {
                    part.replace('<', "\\<")
                } else {
                    part.to_owned()
                }
            })
            .collect::<Vec<_>>()
            .join("`")
    }
}

/// The marker of a fenced code block in [`Page::prose`]: three or more
/// backticks or tildes.
#[derive(Clone, Copy)]
struct Fence {
    /// The marker's character, `` ` `` or `~`.
    marker: char,
    /// How many times the opening line repeats it.
    len: usize,
}

impl Fence {
    /// The fence `line` opens, if it is an opening fence.
    fn open(line: &str) -> Option<Self> {
        let line = line.trim_start();
        let marker = line.chars().next().filter(|c| matches!(c, '`' | '~'))?;
        let len = line.chars().take_while(|&c| c == marker).count();
        (len >= 3).then_some(Self { marker, len })
    }

    /// Whether `line` closes the fence: only its marker, at least as many
    /// times as the opening line.
    fn closes(self, line: &str) -> bool {
        let line = line.trim();
        let len = line.chars().take_while(|&c| c == self.marker).count();
        len >= self.len && len == line.chars().count()
    }
}

#[cfg(test)]
mod tests {
    use super::Page;

    #[test]
    fn prose_keeps_code_blocks_as_they_are() {
        let text = "Text that may\nreference <name>.\n\n```text\n\"${{ a }}\"  -> <a>\n```\nAfter.";
        assert_eq!(
            Page::prose(text),
            "Text that may reference \\<name>.\n\n```text\n\"${{ a }}\"  -> <a>\n```\n\nAfter."
        );
    }

    #[test]
    fn prose_closes_code_blocks_only_on_a_matching_fence() {
        let text = "````markdown\n```text\n<a>\n```\n````\nAfter <b>.\n\n~~~\n<c>\n~~~";
        assert_eq!(
            Page::prose(text),
            "````markdown\n```text\n<a>\n```\n````\n\nAfter \\<b>.\n\n~~~\n<c>\n~~~"
        );
    }
}
